  "We also text them the link. Good for supervisors who don’t check email. The number is deleted after 30 days.": "Мы также пришлём ссылку по SMS — удобно для тех, кто не проверяет почту. Номер удаляется через 30 дней.",
  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer} проверит и подпишет это на странице «Мои задания» в VolunTrack — письмо не отправляется.",
  "The task organizer": "Организатор задания",
  "Your supervisor will get an email with a link to review these hours. If they approve, they'll sign right there to confirm it — if they reject, no signature is needed. This usually takes a day or two.": "Руководитель получит письмо со ссылкой для проверки часов. Если он их одобрит, распишется там же; если отклонит — подпись не нужна. Обычно это занимает день-два.",
  "Supervisor signature": "Подпись руководителя",
