  "Show all {n} upcoming tasks": "Показать все предстоящие задания ({n})",
  "Recently": "Недавно",
  "· Organized by": "· Организатор:",
  "Waiting for your OK": "Ждёт вашего согласия",
  "Your child is under 13, so these sign-ups reach the organizer only after you approve them.": "Ребёнку меньше 13 лет, поэтому эти записи дойдут до организатора только после вашего одобрения.",
  "The organizer's waiver: approving also agrees to it for your child": "Отказ от претензий организатора: одобряя, вы принимаете его и за ребёнка",
  "Approve": "Одобрить",
  "Decline": "Отклонить",
  "Language": "Язык",
  "Other language…": "Другой язык…",
  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "Откройте VolunTrack в браузере телефона (Chrome или Safari) кнопкой ниже и войдите.",
  "Then use the browser’s translate, as shown below.": "Затем воспользуйтесь переводом браузера, как показано ниже.",
  "Use VolunTrack in another language": "VolunTrack на другом языке",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "VolunTrack доступен на английском, испанском, вьетнамском и китайском, а основные экраны — на хинди, арабском, португальском, французском, бенгальском, русском и японском. Для любого другого языка браузер может перевести страницу. Это бесплатно и работает для более чем 100 языков, например тагальского, корейского, гаитянского креольского, немецкого и урду.",
  "computer": "компьютер",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "Щёлкните правой кнопкой в любом месте страницы, выберите «Перевести на…» и свой язык.",
  "Android phone": "Телефон Android",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "Нажмите ⋮ (справа вверху), затем «Перевести…» и выберите язык.",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "Нажмите меню страницы (aA или значок слева от адресной строки), затем «Перевести на…».",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "Нажмите значок перевода в адресной строке или выберите «Вид → Перевод».",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "Перевод выполняет браузер, а не VolunTrack, и он может быть неточным. Письма по-прежнему приходят на английском или на выбранном в VolunTrack языке.",
  "Open in browser": "Открыть в браузере",
  "Got it": "Понятно",
  "Default": "Обычный",
  "Large": "Крупный",
  "Extra large": "Очень крупный",
  "Text size": "Размер текста",
  "High contrast": "Высокий контраст",
  "Easy-read font": "Удобочитаемый шрифт",
  "Accessibility": "Специальные возможности",
  "Make VolunTrack easier to read. These settings are saved on this device only.": "Сделайте VolunTrack удобнее для чтения. Эти настройки сохраняются только на этом устройстве.",
  "Brighter text, stronger borders and focus outlines, and underlined links.": "Ярче текст, чётче рамки и контуры фокуса, ссылки подчёркнуты.",
  "A font that keeps similar letters like I, l and 1 easy to tell apart. Can help with dyslexia or low vision.": "Шрифт, в котором легко различать похожие буквы, например I, l и 1. Может помочь при дислексии или слабом зрении.",
  "The short version": "Кратко",
  "The full": "Полные",
  "are what count.": "имеют решающую силу.",
  "Set a goal and your dashboard will show how close you are. You can change it any time in Settings.": "Поставьте цель, и на главной будет видно, сколько осталось. Изменить её можно в любое время в настройках.",
  "Goal name": "Название цели",
  "e.g. Summer service hours": "напр., Летние часы служения",
  "Due by (optional)": "Срок (необязательно)",
  "Skip for now": "Пока пропустить",
  "Save goal": "Сохранить цель",
  "Link your school": "Привяжите школу",
  "You're linked to your school. Hours you log will show up for your coordinator to review.": "Вы привязаны к школе. Записанные часы будут видны координатору для проверки.",
  "School code": "Код школы",
  "Go to my dashboard": "На мою главную",
  "Password recovery code:": "Код восстановления пароля:",
  "Password recovery code ready": "Код восстановления готов",
  "A password recovery code has been emailed to": "Код восстановления пароля отправлен на",
  ". It expires in 15 minutes.": ". Он действует 15 минут.",
  "Look for an email from": "Ищите письмо от",
  "Don't see it? Check the Spam folder and Promotions/Updates tab.": "Не видите? Проверьте «Спам» и вкладки «Промоакции/Оповещения».",
  "This deployment is a static site, so there’s no email server reachable from here. The password recovery code is shown below — only you can see this screen.": "Это статический сайт, отсюда нет доступа к почтовому серверу. Код восстановления показан ниже — этот экран видите только вы.",
  "Email delivery is not available right now": "Отправка писем сейчас недоступна",
  ". Use the code below to continue.": ". Используйте код ниже, чтобы продолжить.",
  "Add": "Добавьте",
  "to your": "в ваш",
  "and restart the backend to enable real email.": "и перезапустите сервер, чтобы включить настоящую почту.",
  "Retrying…": "Повторяем…",
