  "Forgot password?": "Забыли пароль?",
  "Enter the email on your account and we’ll email a password recovery code.": "Введите почту вашего аккаунта, и мы пришлём код восстановления пароля.",
  "SMTP isn’t configured. Add": "SMTP не настроен. Добавьте",
  "your email credentials": "данные вашей почты",
