  "Choose a new password": "Придумайте новый пароль",
  "Make it at least 8 characters. If you requested a reset, use the recovery code sent above.": "Не меньше 8 символов. Если вы запросили сброс, используйте код восстановления из письма.",
  "Recovery code": "Код восстановления",
