  "Join {school} on VolunTrack": "Присоединяйтесь к {school} в VolunTrack",
  "Join your school on VolunTrack": "Присоединяйтесь к своей школе в VolunTrack",
  "Track your volunteer hours free and send them to your school for approval.": "Бесплатно учитывайте волонтёрские часы и отправляйте их в школу на подтверждение.",
  "Could not join that school.": "Не удалось присоединиться к этой школе.",
  "We could not find that school": "Мы не нашли эту школу",
  "The link may be out of date. Ask your adviser for the current link or school code.": "Возможно, ссылка устарела. Попросите у куратора актуальную ссылку или код школы.",
  "Enter a school code": "Ввести код школы",
