  "Something went wrong": "Что-то пошло не так",
  "We could not look up this school just now. Try again in a minute.": "Сейчас не получается найти эту школу. Попробуйте через минуту.",
  "Log your volunteer hours and send them to {school} for approval. Free for students.": "Записывайте волонтёрские часы и отправляйте их в {school} на подтверждение. Бесплатно для учеников.",
