  "School code: {code}": "Код школы: {code}",
  "Only student accounts join a school. You are signed in with a different kind of account.": "К школе присоединяются только аккаунты учеников. Вы вошли с другим типом аккаунта.",
  "You're in {school}": "Вы в {school}",
