  "Transfer requested": "Перевод запрошен",
  "{school} has been asked to accept your transfer.": "{school} попросили принять ваш перевод.",
  "You are already linked to another school. Joining asks {school} to accept your transfer, and your hours move with you.": "Вы уже привязаны к другой школе. Присоединение отправит {school} запрос на перевод, и ваши часы перейдут с вами.",
  "Your hours will go to {school} for approval.": "Ваши часы будут отправляться в {school} на подтверждение.",
