  "Need help getting started?": "Нужна помощь, чтобы начать?",
  "Create an account, set your first goal, and log your first volunteer hours to earn a badge.": "Создайте аккаунт, поставьте первую цель и запишите первые волонтёрские часы, чтобы получить значок.",
  "Secure sign in": "Безопасный вход",
