  "PIN reset complete": "PIN-код сброшен",
  "Your new PIN has been saved. Return to login and unlock with your 4-digit PIN.": "Новый PIN-код сохранён. Вернитесь ко входу и разблокируйте аккаунт 4-значным PIN-кодом.",
  "Reset your PIN": "Сброс PIN-кода",
