  "Add a school and they'll get a link to finish setup themselves.": "Добавьте школу, и она получит ссылку, чтобы сама закончить настройку.",
  "Set up": "Настроена",
  "Expired": "Истекло",
  "Someone new running the organization?": "Организацией теперь руководит кто-то другой?",
  "Hand this organization’s account to them. They get an email to accept and set their own password. When they do, this login is removed from the organization and signed out.": "Передайте ему аккаунт организации. Он получит письмо, чтобы принять и задать свой пароль. Когда он примет, этот вход будет удалён из организации и выйдет из аккаунта.",
  "They'll get an email with a link to set their own password and school code. The link expires in 3 days.": "Они получат письмо со ссылкой, чтобы задать свой пароль и код школы. Ссылка действует 3 дня.",
  "Send invite": "Отправить приглашение",
