  "Approved hours only": "Только одобренные",
  "Approved + pending": "Одобренные + на рассмотрении",
  "None of your students has a grade on their account yet, so there is nothing to group.": "Ни у одного ученика в аккаунте пока не указан класс, поэтому группировать нечего.",
  "Preview / print": "Предпросмотр / печать",
  "Counted": "Учтено",
  "Short by": "Не хватает",
  "Met": "Выполнено",
  "Missed": "Не выполнено",
  "No hour requirement applies to {grade}. Add one for this grade (or a school-wide total) in Requirements.": "Для {grade} нет нормы часов. Добавьте её для этого класса (или общую для школы) в «Требованиях».",
  "Who in a grade met the hour requirement, due {date}.": "Кто в классе выполнил норму часов к {date}.",
  "Who in a grade met the hour requirement.": "Кто в классе выполнил норму часов.",
