  "No students in {grade}.": "В {grade} нет учеников.",
  "1 student has no grade on their account and is not in any grade’s report.": "У 1 ученика в аккаунте не указан класс, и он не попал ни в один отчёт по классам.",
  "{n} students have no grade on their account and are not in any grade’s report.": "Учеников без класса в аккаунте, не попавших ни в один отчёт по классам: {n}.",
  "Logo": "Логотип",
