  "Preparing your logo…": "Готовим логотип…",
  "Drop your logo here or click to upload": "Перетащите логотип сюда или нажмите, чтобы загрузить",
  "PNG, JPEG, WebP, GIF, or SVG · resized to fit automatically": "PNG, JPEG, WebP, GIF или SVG · размер подгоняется автоматически",
  "Logo link": "Ссылка на логотип",
  "A logo link must start with https://": "Ссылка на логотип должна начинаться с https://",
  "Use a link to an image instead": "Указать ссылку на изображение",
  "Branding saved. Sign-in pages on your domain pick it up within 10 minutes.": "Оформление сохранено. Страницы входа на вашем домене обновятся в течение 10 минут.",
  "Loading branding…": "Загружаем оформление…",
  "Accent colour": "Акцентный цвет",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "Значение в формате hex. Используется для акцентов на странице входа — не для текста и фона кнопок, поэтому любой цвет останется читаемым. Оставьте пустым для зелёного цвета VolunTrack.",
  "Enter a hex value like #2f855a.": "Введите значение hex, например #2f855a.",
  "Preview": "Предпросмотр",
  "Save branding": "Сохранить оформление",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "Это оформление действует для собственных адресов вашей организации. Каждая школа оформляет свои отдельно.",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "Меняется только страница входа вашей школы. Название и логотип VolunTrack остаются на основном сайте.",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "Оформление появляется только на вашем собственном адресе. Рабочего домена у вас пока нет — сначала настройте его в разделе «Собственный домен», и тогда всё сохранённое здесь появится на его странице входа.",
  "Shown at sign-in on": "Показывается при входе на",
  "Set how many hours your students need (one total, or per grade) to see who is behind.": "Укажите, сколько часов нужно ученикам (общая норма или по классам), чтобы видеть, кто отстаёт.",
  "Allow pop-ups for this site to print the certificates.": "Разрешите всплывающие окна для этого сайта, чтобы распечатать сертификаты.",
  "Print certificates ({n})": "Распечатать сертификаты ({n})",
  "Only students with hours to go": "Только ученики, которым ещё нужны часы",
  "Everyone has met their hours. 🎉": "Все выполнили норму. 🎉",
  "{n} to go": "Осталось: {n}",
  "No goal for this grade": "Для этого класса нет цели",
  "Nothing logged yet": "Пока ничего не записано",
  "Select all ({n})": "Выбрать все ({n})",
  "Yes, send": "Да, отправить",
  "Email reminder": "Напоминание по почте",
  "Each student gets at most one reminder every {n} days.": "Каждый ученик получает не больше одного напоминания раз в {n} дн.",
  "{n} of {total} students still have hours to go": "Учеников, которым ещё нужны часы: {n} из {total}",
  "due {date}": "срок {date}",
