  "Skip to content": "Перейти к содержимому",
  "Weekly adviser email": "Еженедельное письмо куратору",
  "On. Every Monday we email you what needs your review, who is behind on hours and what students logged that week.": "Включено. Каждый понедельник мы присылаем, что ждёт вашей проверки, кто отстаёт по часам и что ученики записали за неделю.",
  "Off. We won't email you a weekly summary.": "Выключено. Мы не будем присылать еженедельную сводку.",
