  "The organizer of an event {name} signed up for sees this on their check-in list, only around the day of the event. It isn’t shown anywhere else.": "Организатор мероприятия, на которое записан(а) {name}, видит это в своём списке отметок, только около дня мероприятия. Больше нигде это не показывается.",
  "Change": "Изменить",
