  "Saved on this device. It sends by itself when you’re back online.": "Сохранено на этом устройстве. Отправится само, когда вы снова будете онлайн.",
  "Waiting to send": "Ждёт отправки",
  "Could not make the packet.": "Не удалось собрать пакет.",
  "End-of-year packet": "Пакет на конец года",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "Один ZIP с папкой для каждой школы: сводка, все записи и отчёт о часах каждого ученика.",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "Один ZIP со сводкой, всеми записями, историей одобрений, сертификатами для учеников, выполнивших норму, и отчётом о часах каждого ученика.",
  "School year": "Учебный год",
  "Making student reports… {done} of {total}": "Готовим отчёты учеников… {done} из {total}",
  "Making the packet…": "Собираем пакет…",
  "Download packet": "Скачать пакет",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "Учебный год — с 1 августа по 31 июля. В ZIP есть личные данные учеников, поэтому храните его в надёжном месте.",
  "A parent or guardian must come with you to this event. Who is coming? (their name)": "На это мероприятие с вами должен прийти родитель или опекун. Кто придёт? (его имя)",
  "Parent coming: {name}": "Придёт родитель: {name}",
