  "When are you usually free?": "Когда вы обычно свободны?",
  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "Отметьте удобное время. Тогда «Когда я свободен» покажет только мероприятия, которые начинаются в это время. Это видите только вы.",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "Утро — до полудня, день — с полудня до 17:00, вечер — после 17:00.",
  "Could not save when you are free.": "Не удалось сохранить свободное время.",
