  "Ask them to confirm hours": "Попросить подтвердить часы",
  "Emailed to {email}.": "Отправлено на {email}.",
  "Copy this link to them:": "Скопируйте им эту ссылку:",
  "{n} entries waiting. Works for {days} days; a new link replaces this one.": "Ждут записей: {n}. Действует {days} дн.; новая ссылка заменит эту.",
  "Sign-off link": "Ссылка для подтверждения",
  "Confirmed by a parent: {name}": "Подтвердил родитель: {name}",
  "Could not check you out.": "Не удалось отметить уход.",
  "You stayed {stayed} of the {minimum} minutes this event asks for, so the organizer will review your hours.": "Вы пробыли {stayed} из {minimum} минут, которые требует это мероприятие, поэтому организатор проверит ваши часы.",
  "1 hour sent to the organizer to sign.": "1 час отправлен организатору на подпись.",
