  "Guests of approved volunteers": "Гости одобренных волонтёров",
  "Show-up rate counts volunteers you approved who were marked present or checked in, out of those plus anyone marked absent. Excused volunteers and anyone not yet marked aren't counted. Hours are approved hours logged on the task.": "Доля пришедших — это одобренные вами волонтёры, отмеченные присутствующими или отметившиеся, из их числа плюс всех отмеченных отсутствующими. Волонтёры с уважительной причиной и ещё не отмеченные не учитываются. Часы — это одобренные часы, записанные по заданию.",
  "QR code to sign on a phone": "QR-код для подписи на телефоне",
  "Fall": "Осень",
  "Spring": "Весна",
  "Term goals": "Цели на четверть",
  "Split the year into terms, each with its own hours. Students see this term’s progress, and you see who is behind this term. Hours count toward the term they were logged in.": "Разделите год на периоды, у каждого свои часы. Ученики видят прогресс за текущий период, а вы — кто в нём отстаёт. Часы засчитываются в тот период, когда они записаны.",
