  "Love VolunTrack?": "Нравится VolunTrack?",
  "You've logged your first volunteer session. We'd love to hear how it's going for you!": "Вы записали первое волонтёрское занятие. Будем рады узнать, как у вас дела!",
  "Rate your experience": "Оцените впечатления",
  "Tell us what you like or what could be better...": "Расскажите, что нравится и что можно улучшить...",
