  "Sign in on your phone and scan. A code appears under your name here: type it on your phone.": "Войдите на телефоне и отсканируйте. Здесь под вашим именем появится код: введите его на телефоне.",
  "Could not open the kiosk.": "Не удалось открыть киоск.",
