  "Set a kiosk exit code": "Задайте код выхода из киоска",
  "Pick 4 digits only you know. You’ll need them to leave the kiosk or unlock a name, so volunteers can’t get into your account.": "Выберите 4 цифры, которые знаете только вы. Они понадобятся, чтобы выйти из киоска или разблокировать имя, — так волонтёры не попадут в ваш аккаунт.",
  "Check in and out": "Отметка прихода и ухода",
  "Organizer: exit kiosk": "Организатор: выйти из киоска",
