  "Several time slots or roles, each with its own spots. Volunteers pick one.": "Несколько интервалов времени или ролей, у каждого свои места. Волонтёры выбирают один.",
  "Pick a pin on the map above so this task can be sorted by distance.": "Поставьте метку на карте выше, чтобы задание сортировалось по расстоянию.",
