  "Average rating from volunteers who came": "Средняя оценка от пришедших волонтёров",
  "Comments are anonymous. If one breaks the rules, contact us from Help.": "Комментарии анонимны. Если какой-то нарушает правила, напишите нам из раздела «Помощь».",
  "Check-in QR": "QR для отметки",
  "A tablet at the door: volunteers tap their name and enter the PIN from their approval email.": "Планшет у входа: волонтёры нажимают на своё имя и вводят PIN-код из письма об одобрении.",
