  "Bring gloves and water. Park at the back of the lot.": "Возьмите перчатки и воду. Паркуйтесь в дальней части стоянки.",
  "Sent one message per person — volunteers never see each other's addresses.": "Каждому отправлено отдельное сообщение — волонтёры не видят адреса друг друга.",
  "Cancel this event": "Отменить это мероприятие",
  "Reason (optional) — included in the email": "Причина (необязательно) — войдёт в письмо",
  "Everyone signed up is emailed. Attendance already recorded is kept, and the event cannot be reopened.": "Все записавшиеся получат письмо. Уже отмеченные посещения сохранятся, а мероприятие нельзя будет открыть снова.",
