  "My Students": "Мои ученики",
  "No approved students yet — approve a signup above to see them here.": "Одобренных учеников пока нет — одобрите запись выше, чтобы они появились здесь.",
  "No logged hours yet.": "Записанных часов пока нет.",
  "Signed & approved": "Подписано и одобрено",
  "Log hours for volunteer": "Записать часы волонтёру",
  "Add a waiver volunteers must agree to": "Добавить согласие, которое должны принять волонтёры",
  "Waiver (optional)": "Согласие (необязательно)",
  "Paste your organization's waiver or release. Volunteers agree by typing their name; for anyone under 18, a parent or guardian agrees too.": "Вставьте текст согласия или отказа от претензий вашей организации. Волонтёры соглашаются, вводя своё имя; за тех, кому меньше 18, соглашается и родитель или опекун.",
  "Thank you": "Спасибо",
  "Almost done. Pick your account type and fill in the rest. You won’t need a password: sign in with the same button next time.": "Почти готово. Выберите тип аккаунта и заполните остальное. Пароль не понадобится: в следующий раз входите той же кнопкой.",
  "Log some hours first, then make your résumé.": "Сначала запишите часы, а потом составьте резюме.",
  "Download résumé": "Скачать резюме",
  "Sign-in didn't complete": "Вход не завершён",
  "Signing you in…": "Выполняем вход…",
  "Finishing up with your school's login.": "Завершаем вход через вашу школу.",
  "Verify a volunteer transcript": "Проверка волонтёрской выписки",
  "Not verified": "Не подтверждено",
  "Genuine and unaltered": "Подлинная и без изменений",
  "Issued by VolunTrack for": "Выдано VolunTrack для",
  "Signed with a signing key that has since been rotated. It is still valid.": "Подписано ключом, который с тех пор заменён. Выписка по-прежнему действительна.",
  "Approved hours": "Одобренные часы",
  "Verification": "Проверка",
  "Found a bug, have a feature request, or just want to say hi? We'd love to hear from you.": "Нашли ошибку, хотите предложить функцию или просто поздороваться? Будем рады вашему сообщению.",
  "Check that a VolunTrack transcript is genuine and has not been changed since it was issued. No account needed. The file is checked by our server and not stored.": "Проверьте, что выписка VolunTrack подлинная и не менялась после выдачи. Аккаунт не нужен. Файл проверяет наш сервер и не сохраняет его.",
  "Finish setting up your organization": "Завершите настройку организации",
  "Register your organization": "Зарегистрируйте организацию",
  "You were invited by a VolunTrack admin. Just set your password.": "Вас пригласил администратор VolunTrack. Просто задайте пароль.",
  "Manage multiple schools under one account, using the registration code we sent you.": "Управляйте несколькими школами в одном аккаунте с помощью кода регистрации, который мы вам прислали.",
  "Contact email": "Контактная почта",
