  "People who didn’t sign up can scan this code to join and check in, while there are spots left.": "Те, кто не записывался, могут отсканировать этот код, чтобы присоединиться и отметиться, пока есть места.",
  "Join as a walk-in?": "Присоединиться без записи?",
